// Задание 4: Циклическое управление реле
const int relayPin = 12;
const unsigned long ON_TIME = 11000; // 11 секунд
const unsigned long OFF_TIME = 3000;  // 3 секунды

void setup() {
  pinMode(relayPin, OUTPUT);
  digitalWrite(relayPin, LOW);
}

void loop() {
  digitalWrite(relayPin, HIGH);
  delay(ON_TIME);

  digitalWrite(relayPin, LOW);
  delay(OFF_TIME);
}
